local function _0x_decode(_0x_data, _0x_k)
	local _0x_len = #_0x_data
	local _0x_out = {}
	local _0x_idx = 1
	local _rshift = _b32.rshift
	local _lshift = _b32.lshift
	local _bxor = _b32.bxor
	local _bor = _b32.bor
	local _band = _b32.band
	local _schar = string.char
	local _sbyte = string.byte

	local _0x_i = 1
	while _0x_i <= _0x_len do
		local _c1 = _0x_map[_sbyte(_0x_data, _0x_i)] or 0
		local _c2 = _0x_map[_sbyte(_0x_data, _0x_i + 1)] or 0
		local _b3 = _sbyte(_0x_data, _0x_i + 2)
		local _b4 = _sbyte(_0x_data, _0x_i + 3)
		local _c3 = _0x_map[_b3] or 0
		local _c4 = _0x_map[_b4] or 0

		local _n = _bor(_lshift(_c1, 18), _lshift(_c2, 12), _lshift(_c3, 6), _c4)

		_0x_out[_0x_idx] = _schar(_bxor(_band(_rshift(_n, 16), 255), _0x_k))
		_0x_idx = _0x_idx + 1

		if _b3 ~= 61 then
			_0x_out[_0x_idx] = _schar(_bxor(_band(_rshift(_n, 8), 255), _0x_k))
			_0x_idx = _0x_idx + 1
		end
		if _b4 ~= 61 then
			_0x_out[_0x_idx] = _schar(_bxor(_band(_n, 255), _0x_k))
			_0x_idx = _0x_idx + 1
		end
		_0x_i = _0x_i + 4
	end
	return table.concat(_0x_out)
end

local function _0x_launchCore(decryptionKey)
	local _targetLoader = loadstring or load
	local isTampered = false
	pcall(function()
		if debug and debug.info then
			local src = debug.info(_targetLoader, "s")
			if src and src ~= "[C]" and src ~= "=[C]" and not string.find(src, "builtin") then
				isTampered = true
			end
		elseif debug and debug.getinfo then
			local info = debug.getinfo(_targetLoader)
			if info and info.what and info.what == "Lua" then
				isTampered = true
			end
		end
	end)
	if isTampered then
		return
	end

	local _key = decryptionKey or 0
	local _state = 0xA1
	local segments, source, fn, err
	while _state ~= 0x00 do
		if _state == 0xA1 then
			segments = {}
			_state = 0xB4
		elseif _state == 0xB4 then
			for idx, c in ipairs(_0x_chunks) do
				segments[idx] = _0x_decode(c, _key)
			end
			_state = 0xC7
		elseif _state == 0xC7 then
			source = table.concat(segments)
			segments = nil
			fn, err = _targetLoader(source)
			source = nil
			_state = 0xD9
		elseif _state == 0xD9 then
			if not fn then
				return
			end
			_state = 0x00
			return fn()
		end
	end
end

local _0x_free = true

if _0x_free then
	notifyUser("Ziro Hub", "Acesso Livre Ativado! Carregando sistemas...", 3)
	task.spawn(function()
		_0x_launchCore(_0x_c._k)
	end)
	return
end

local function _0x_retrieve()
	local key = nil
	pcall(function()
		if getgenv and getgenv()._ZIRO_ACTIVE_KEY and type(getgenv()._ZIRO_ACTIVE_KEY) == "string" then
			key = getgenv()._ZIRO_ACTIVE_KEY
		elseif shared and shared._ZIRO_ACTIVE_KEY and type(shared._ZIRO_ACTIVE_KEY) == "string" then
			key = shared._ZIRO_ACTIVE_KEY
		end
	end)
	if key and key ~= "" then return key:gsub("%s+", ""):upper() end

	pcall(function()
		if readfile then
			local content = readfile(_0x_c._f)
			if content and type(content) == "string" and content ~= "" then
				key = content
			end
		end
	end)
	if key and key ~= "" then return key:gsub("%s+", ""):upper() end

	pcall(function()
		if isfile and isfile(_0x_c._f) and readfile then
			local content = readfile(_0x_c._f)
			if content and type(content) == "string" and content ~= "" then
				key = content
			end
		end
	end)

	if key and key ~= "" then
		return key:gsub("%s+", ""):upper()
	end
	return nil
end

local function _0x_persist(validKey)
	local cleanKey = validKey:gsub("%s+", ""):upper()
	pcall(function()
		if getgenv then getgenv()._ZIRO_ACTIVE_KEY = cleanKey end
		if shared then shared._ZIRO_ACTIVE_KEY = cleanKey end
	end)
	pcall(function()
		if writefile then
			writefile(_0x_c._f, cleanKey)
		end
	end)
	pcall(function()
		local qot = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
		if qot then
			qot('pcall(function() if getgenv then getgenv()._ZIRO_ACTIVE_KEY = "' .. cleanKey .. '" end end)')
		end
	end)
end

local function _0x_invalidate()
	pcall(function()
		if writefile then writefile(_0x_c._f, "") end
		if delfile then delfile(_0x_c._f) end
		if getgenv then getgenv()._ZIRO_ACTIVE_KEY = nil end
		if shared then shared._ZIRO_ACTIVE_KEY = nil end
	end)
end

local candidateKey = _0x_retrieve()
local initialErrorMsg = nil

if candidateKey and candidateKey ~= "" then
	local ok, decKey, msg = _0x_validate(candidateKey)
	if ok then
		_0x_persist(candidateKey)
		notifyUser("Ziro Hub | Autenticacao", "Chave ativa autorizada! Carregando sistemas...", 3)
		task.spawn(function()
			_0x_launchCore(decKey)
		end)
		return
	else
		_0x_invalidate()
		initialErrorMsg = "Ultima chave expirada ou invalida. Digite uma nova chave."
		notifyUser("Ziro Hub | Acesso Bloqueado", initialErrorMsg, 4)
	end
end

