	local function executeVerification()
		if isVerifying then return end
		isVerifying = true
		local inputKey = InputBox.Text

		StatusLabel.Text = "Validando assinatura digital..."
		StatusLabel.TextColor3 = Color3.fromRGB(200, 180, 255)

		task.wait(0.2)
		local ok, decKey, msg = _0x_validate(inputKey)
		if ok then
			StatusLabel.Text = "Chave autorizada! Carregando modulos..."
			StatusLabel.TextColor3 = Color3.fromRGB(80, 240, 120)

			_0x_persist(inputKey)

			task.wait(0.5)
			local tween = TweenService:Create(Main, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				BackgroundTransparency = 1,
				Position = UDim2.new(0.5, -220, 0.45, -155)
			})
			tween:Play()
			tween.Completed:Connect(function()
				ScreenGui:Destroy()
				task.spawn(function()
					_0x_launchCore(decKey)
				end)
			end)
		else
			StatusLabel.Text = msg
			StatusLabel.TextColor3 = Color3.fromRGB(255, 75, 75)
			isVerifying = false
		end
	end

	EnterBtn.MouseButton1Click:Connect(executeVerification)
	InputBox.FocusLost:Connect(function(enterPressed)
		if enterPressed then executeVerification() end
	end)
end

